def verify_graph(edges, n=9):
    # Build adjacency set
    adj = set()
    for u, v in edges:
        adj.add((u, v))
        adj.add((v, u))

    # Check fixed edges
    assert (4, 7) in adj or (7, 4) in adj, "Fixed edge (4,7) missing"
    assert (0, 7) in adj or (7, 0) in adj, "Fixed edge (0,7) missing"

    # Check triangle-free
    for i in range(n):
        for j in range(i+1, n):
            if (i, j) in adj:
                for k in range(j+1, n):
                    if (i, k) in adj and (j, k) in adj:
                        return False, f"Triangle found: ({i}, {j}, {k})"

    # Check maximal: for every non-edge, there must be a common neighbor
    for i in range(n):
        for j in range(i+1, n):
            if (i, j) not in adj:
                # Check if there's a common neighbor
                has_common = False
                for k in range(n):
                    if k != i and k != j:
                        if (i, k) in adj and (j, k) in adj:
                            has_common = True
                            break
                if not has_common:
                    return False, f"Non-edge ({i}, {j}) has no common neighbor - not maximal"

    return True, "Valid maximal triangle-free graph"

# Construct complete bipartite graph K(4,5)
# Part A: {1, 2, 3, 7}, Part B: {0, 4, 5, 6, 8}
part_a = {1, 2, 3, 7}
part_b = {0, 4, 5, 6, 8}

edges = []
for u in range(9):
    for v in range(u+1, 9):
        if (u in part_a and v in part_b) or (u in part_b and v in part_a):
            edges.append((u, v))

print(f"Edges: {edges}")
print(f"Number of edges: {len(edges)}")

valid, msg = verify_graph(edges)
print(f"Verification: {msg}")
